select ('78c00000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','radar-c-'||n||'@example.invalid',now(),now(),now() from generate_series(1,3)n;
insert into public.platform_admins(user_id) values('78c00000-0000-4000-8000-000000000001'),('78c00000-0000-4000-8000-000000000003');
