create temp table ids(k text primary key,id uuid); grant all on ids to authenticated;
create function pg_temp.id(k text) returns uuid language sql as $$select id from ids where ids.k=$1$$;
create function pg_temp.hrev() returns int language sql as $$select (public.get_radar_hypothesis(pg_temp.id('h'))->>'revision')::int$$;
create function pg_temp.input() returns jsonb language sql as $$select '{"title":"Repeated coordination effort","problem_statement":"Small software teams may repeat coordination across tools.","affected_context":"Small software teams","hypothesis_language":"en","open_questions":"Which workflows?","counter_observations":"Some teams use one tool.","evidence_limits":"Limited coverage."}'::jsonb$$;
create function pg_temp.handoff(req uuid default '78c00000-0000-4000-8000-000000000010') returns uuid language sql as $$select public.handoff_radar_hypothesis(pg_temp.id('h'),pg_temp.hrev(),req,'Private exploration','My own starting description',array[pg_temp.id('s1')],array[pg_temp.id('s1')],true)$$;
-- Purpose-bound synthetic fixtures. Reviews below use production APIs.
insert into public.radar_sources(id,name,domain,allowed_path,source_type,retrieval_method,is_public,permission_state,status,source_language,region,target_context,source_nature,source_origin,review_due_at,revision)
values('78c00000-0000-4000-8000-000000000101','Fixture source A','fixture.invalid','/','public_web','manual_url',true,'approved','active','en','unknown','IT small teams','direct','primary',now()+interval '90 days',2),
