select ('78c00000-0000-4000-8000-'||lpad((200+n)::text,12,'0'))::uuid,case when n=1 then '78c00000-0000-4000-8000-000000000101'::uuid else '78c00000-0000-4000-8000-000000000102'::uuid end,'https://fixture.invalid/'||n,case when n=1 then '2026-09-01'::date when n=2 then '2026-10-01'::date end,case when n=1 then 'en' else 'de' end,'en','Summary fixture '||n,'Observation fixture '||n,'Small teams',array['workflow'],'relevant',now()+interval '180 days',null,3,2,'fixture-'||n from generate_series(1,3)n;
