create function pg_temp.fail_import() returns trigger language plpgsql as $$begin if new.type='assumption' then raise exception 'synthetic_import_failure'; end if; return new; end$$;
create trigger synthetic_import_failure before insert on public.network_problem_workspace_entries for each row execute function pg_temp.fail_import();
set local role authenticated;
